 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    separators_r = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] in (4, 7)]
    separators_c = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] in (4, 7)]
    rb = [-1] + separators_r + [h]
    cb = [-1] + separators_c + [w]
    tiles = [(rb[i]+1, rb[i+1], cb[j]+1, cb[j+1]) for i in range(len(rb)-1) for j in range(len(cb)-1)]
    if separators_r and separators_c:
        # Find the unique non-background pattern in a tile and replicate it to each tile.
        bg = 9 if 9 in sum(g, []) else (5 if 5 in sum(g, []) else 2)
        candidates=[]
        for a,b,c,d in tiles:
            vals=[g[r][x] for r in range(a,b) for x in range(c,d)]
            if any(v != bg for v in vals):
                candidates.append((a,b,c,d))
        if candidates:
            a,b,c,d=candidates[0]
            template=[g[r][c:d] for r in range(a,b)]
            for x,y,u,v in tiles:
                if (y-x,v-u)==(len(template),len(template[0])):
                    for i in range(y-x):
                        g[x+i][u:v]=template[i][:]
        return g
    # A single separator line: repeat the non-background pattern periodically
    # in each panel along the dimension divided by the separator.
    if separators_r:
        bounds=[-1]+separators_r+[h]
        for i in range(len(bounds)-1):
            a,b=bounds[i]+1,bounds[i+1]
            if b-a and i != 0:
                # Copy the first panel's rows, preserving the separator lines.
                src=bounds[0]+1
                for r in range(a,b): g[r]=g[src+(r-a)%(bounds[1]-bounds[0]-1)][:]
        return g
    if separators_c:
        bounds=[-1]+separators_c+[w]
        panels=[(bounds[i]+1,bounds[i+1]) for i in range(len(bounds)-1)]
        source=panels[0]
        for a,b in panels[1:]:
            for r in range(h):
                for c in range(a,b):
                    g[r][c]=g[r][source[0]+(c-a)%(source[1]-source[0])]
        return g
    return g
